-- ============================================================================
-- 2026-08-23_2322  The band check was blind to 9 served documents, on 4 pages it had never scanned
-- ============================================================================
--
-- Found while answering "anything else that still needs to be done", by asking the database rather
-- than remembering. It is a defect in the pass shipped earlier the same morning.
--
-- 🛑 THE BLIND SPOT, AND IT IS THE EXACT ONE THIS WORK EXISTS TO ELIMINATE.
-- Both the inventory the detector was fed and the view that reports on it keyed off
-- `address_row_map.band_y0_pct IS NOT NULL` - the presence of a MANUAL OVERRIDE. Nine served
-- documents still run on DERIVED bands, where that column is NULL and `v_stamp_row_bands` falls
-- back to a stamp-midpoint heuristic. So those nine were never scanned, never reported, and never
-- counted in "0 UNSCANNED". They are on the four pages CLAUDE.md already names as the hardest:
--
--     ticket-311045 p1   106-ALC, 205-SAS
--     ticket-831102 p1   057-BAY, 133-MUT              roster median luma 216
--     ticket-831102 p2   024-GRO, 169-TCE, 076-TCE     roster median luma 215
--     ticket-831325 p1   059-SK, 293-ALC               roster median luma 204
--
-- A derived band is a heuristic over a stamp template that is reused across sheets, so it is NOT on
-- the paper. These nine were the likeliest bands on the fleet to be wrong and the check could not
-- see them. Now scanned: all four pages detect 8 to 14 rules despite the low contrast, and
-- ticket-831102 p2 needed the skew search (gain 10 rows). **All nine are flagged.**
--
-- 🛑 AND A SECOND, SMALLER ONE: THE CHECK WAS READING THE WRONG BAND FOR 6 MORE DOCUMENTS.
-- It read `address_row_map`, which is the band as it stands NOW. What a client opens is the band
-- that was painted when the document was generated, recorded on `redacted_manifest_docs`. Six
-- served documents differ, because a band was edited after the document was made and the sweep has
-- not regenerated it yet. For those six the check was reporting on geometry nobody is looking at,
-- and a leak that is still live would have read as fixed.
--
-- => The view now keys off the SERVED DOCUMENT'S band, which is what the customer sees, and covers
--    every served document rather than only those with an override. Two new columns make the
--    difference visible instead of implicit: `band_is_override` (false = still on a derived band)
--    and `doc_current` (false = the document predates the current band and is awaiting the sweep).
--
-- ⚠ ALSO FIXED, AND IT IS THE SAME CLASS OF MISTAKE AS THE ONE IT BROKE. The header/footer trim
-- decides which rules are "long" enough to be a form bar. It used `run >= 0.70 * maxRun`. On
-- ticket-311045 p1 the two clusters sit at 0.403 and 0.542, a ratio of 1.34, so that threshold
-- marks EVERY rule long and the trim ate eight of the page's twelve rules. The page graded FAILED
-- with "only 4 rules inside the roster" while its rules were a textbook alternation. A fraction of
-- a maximum is not a cluster boundary; the split is now the largest gap in the page's own run
-- values, the trim is capped at two bars per end, and it will not strip a page below six rules.
--
-- RESULT, measured live over all banded rows (647 now, 638 before, the nine being the point):
--     provably ONE_SLOT and ON_RULE     559
--     worklist                           88
--     page grades      OK 152  SPARSE 8  IRREGULAR 2  FAILED 2   (was OK 149 / 6 / 2 / 3 over 160 pages)
--     PART_SLOT reading ON_RULE          29 -> 14
--     SPANS_MULTIPLE reading ON_RULE     10 -> 5
--     in-roster recall vs the 197 hand-recorded rules   99.5% unchanged, mean distance 0.058pp
--
-- ADR 010 rule 8 (audit): unchanged, machine-detected geometry, audit OPT-OUT. The 198 hand-recorded
-- rules are untouched: source is part of the primary key since 2026-08-21_0811, so a DELETE of the
-- machine source cannot reach them, and the VERIFY asserts it.

BEGIN;

DELETE FROM derm.page_row_rules  WHERE source = 'runlen-v2-2026-08-21';
DELETE FROM derm.page_rule_scans WHERE source = 'runlen-v2-2026-08-21';

