DROP VIEW IF EXISTS derm.v_band_edges_off_rule;
DROP VIEW IF EXISTS derm.v_band_edge_check;

CREATE VIEW derm.v_band_edge_check AS
WITH served AS (
  -- 🛑 THE BAND COMES FROM THE DOCUMENT, NOT FROM address_row_map. The document records the band
  -- that was actually painted; the table records the band as it stands now. They differ whenever a
  -- band has been edited and the sweep has not regenerated yet, and it is the painted one the
  -- customer is looking at. Keying off the table also silently excluded every row without a manual
  -- override, which was 9 served documents on 4 never-scanned pages.
  SELECT r.id AS row_id, r.dump_folder,
         COALESCE(r.stamp_page, r.page) AS effective_page,
         c.client_code,
         d.band_y0 AS band_y0_pct, d.band_y1 AS band_y1_pct,
         r.band_source, r.stamp_y_pct,
         (r.band_y0_pct IS NOT NULL) AS band_is_override,
         (r.band_y0_pct IS NULL
          OR (abs(d.band_y0 - r.band_y0_pct) <= 0.001 AND abs(d.band_y1 - r.band_y1_pct) <= 0.001)) AS doc_current,
         d.source_url AS doc_source_url, d.url AS doc_url
    FROM derm.address_row_map r
    JOIN public.clients c ON c.id = r.matched_client_id
    JOIN derm.redacted_manifest_docs d
      ON d.manifest_id = r.matched_manifest_id
     AND d.client_id   = r.matched_client_id
     AND d.effective_page = COALESCE(r.stamp_page, r.page)
   WHERE d.band_y0 IS NOT NULL AND d.band_y1 IS NOT NULL
), scan AS (
  SELECT * FROM derm.page_rule_scans WHERE source = 'runlen-v2-2026-08-21'
), m AS (
  SELECT s.*, sc.grade AS page_grade, sc.n_rules, sc.pitch_pct, sc.source_etag, sc.skew_saturated,
         sc.dump_folder AS scanned,
         t.d AS top_gap_pct, t.kind AS top_kind,
         b.d AS bottom_gap_pct, b.kind AS bottom_kind,
         ib.n AS inner_boundaries, idv.n AS inner_dividers
    FROM served s
    LEFT JOIN scan sc ON sc.dump_folder = s.dump_folder AND sc.effective_page = s.effective_page
    LEFT JOIN LATERAL (
      SELECT abs(pr.rule_pct - s.band_y0_pct) AS d, pr.kind FROM derm.page_row_rules pr
       WHERE pr.dump_folder = s.dump_folder AND pr.effective_page = s.effective_page AND pr.source = 'runlen-v2-2026-08-21'
       ORDER BY abs(pr.rule_pct - s.band_y0_pct) LIMIT 1
    ) t ON true
    LEFT JOIN LATERAL (
      SELECT abs(pr.rule_pct - s.band_y1_pct) AS d, pr.kind FROM derm.page_row_rules pr
       WHERE pr.dump_folder = s.dump_folder AND pr.effective_page = s.effective_page AND pr.source = 'runlen-v2-2026-08-21'
       ORDER BY abs(pr.rule_pct - s.band_y1_pct) LIMIT 1
    ) b ON true
    LEFT JOIN LATERAL (
      SELECT count(*) AS n FROM derm.page_row_rules pr
       WHERE pr.dump_folder = s.dump_folder AND pr.effective_page = s.effective_page
         AND pr.source = 'runlen-v2-2026-08-21' AND pr.kind = 'boundary'
         AND pr.rule_pct > s.band_y0_pct + 0.35 AND pr.rule_pct < s.band_y1_pct - 0.35
    ) ib ON true
    LEFT JOIN LATERAL (
      SELECT count(*) AS n FROM derm.page_row_rules pr
       WHERE pr.dump_folder = s.dump_folder AND pr.effective_page = s.effective_page
         AND pr.source = 'runlen-v2-2026-08-21' AND pr.kind = 'divider'
         AND pr.rule_pct > s.band_y0_pct + 0.35 AND pr.rule_pct < s.band_y1_pct - 0.35
    ) idv ON true
)
SELECT row_id, dump_folder, effective_page, client_code, doc_url,
       band_y0_pct, band_y1_pct, band_source, band_is_override, doc_current,
       page_grade, n_rules, pitch_pct, skew_saturated,
       top_gap_pct, top_kind, bottom_gap_pct, bottom_kind, inner_boundaries, inner_dividers,
       CASE
         WHEN scanned IS NULL                                    THEN 'UNSCANNED'
         WHEN source_etag IS DISTINCT FROM derm._img_etag(doc_source_url) THEN 'STALE'
         WHEN top_gap_pct IS NULL OR bottom_gap_pct IS NULL       THEN 'OFF_RULE'
         WHEN top_gap_pct <= 0.35 AND bottom_gap_pct <= 0.35      THEN 'ON_RULE'
         ELSE 'OFF_RULE'
       END AS edge_verdict,
       CASE
         WHEN scanned IS NULL OR page_grade = 'FAILED'
           OR top_kind = 'unclassified' OR bottom_kind = 'unclassified'
           OR top_kind IS NULL OR bottom_kind IS NULL              THEN 'UNKNOWN'
         WHEN inner_boundaries > 0                                 THEN 'SPANS_MULTIPLE'
         WHEN top_kind = 'boundary' AND bottom_kind = 'boundary'
          AND inner_dividers = 1                                   THEN 'ONE_SLOT'
         WHEN top_kind = 'boundary' AND bottom_kind = 'boundary'    THEN 'ODD_SLOT'
         ELSE 'PART_SLOT'
       END AS slot_verdict
  FROM m;

COMMENT ON VIEW derm.v_band_edge_check IS
  'Every SERVED redaction band, against the printed rules detected on its page. '
  'THE BAND IS READ FROM THE DOCUMENT, not from address_row_map: the document records what was '
  'painted and the table records the band as it stands now, and it is the painted one the customer '
  'is looking at. band_is_override = false means the band is still DERIVED from a stamp-midpoint '
  'template rather than measured, so it is not on the paper. doc_current = false means the band was '
  'edited and the sweep has not regenerated the document yet. '
  'TWO VERDICTS BECAUSE THERE ARE TWO PROPERTIES, and a band is safe only when BOTH hold. '
  'edge_verdict: is a line of TEXT bisected? An edge on any printed rule is not. ON_RULE / '
  'OFF_RULE / UNSCANNED (never scanned, NOT an all-clear) / STALE (image bytes changed since the '
  'scan, compared by etag because x-upsert keeps the URL identical). '
  'slot_verdict: does the band cover exactly ONE client slot? ONE_SLOT / PART_SLOT (an edge on a '
  'mid-slot divider or header bar, so it starts or ends inside somebody else''s slot) / '
  'SPANS_MULTIPLE (a slot boundary lies INSIDE the band) / ODD_SLOT / UNKNOWN. '
  'slot_verdict uses the NEAREST rule''s kind whatever the distance, which is why a band can be '
  'ONE_SLOT and OFF_RULE. Tolerance 0.35pp, about 2-3px on a 720px scan.';

CREATE VIEW derm.v_band_edges_off_rule AS
SELECT *,
       CASE WHEN slot_verdict = 'SPANS_MULTIPLE'            THEN 1
            WHEN slot_verdict IN ('PART_SLOT','ODD_SLOT')   THEN 2
            WHEN edge_verdict IN ('STALE','UNSCANNED')      THEN 3
            WHEN edge_verdict = 'OFF_RULE'                  THEN 4
            ELSE 5 END AS severity
  FROM derm.v_band_edge_check
 WHERE NOT (edge_verdict = 'ON_RULE' AND slot_verdict = 'ONE_SLOT');

COMMENT ON VIEW derm.v_band_edges_off_rule IS
  'The worklist. EMPTY IS HEALTHY. Everything that is not provably one whole slot with no line of '
  'text bisected. severity 1 the band covers more than one client, 2 it starts or ends inside a '
  'slot, 3 never scanned or the image moved, 4 the edges are off the rules but the slot is right. '
  'Check after any stamping session and after any band edit, the same way '
  'derm.v_blackout_blocked_sheets is checked.';

DO $$
DECLARE v_hand int; v_scans int; v_unscanned int; v_stale int; v_derived int; v_lag int;
        v_ok int; v_span int; v_part int; v_dup int;
BEGIN
  SELECT count(*) INTO v_hand FROM derm.page_row_rules WHERE source LIKE 'claude-%';
  IF v_hand <> 198 THEN RAISE EXCEPTION 'the hand-recorded corpus is at % rules, not 198', v_hand; END IF;

  SELECT count(*) INTO v_scans FROM derm.page_rule_scans WHERE source = 'runlen-v2-2026-08-21';
  IF v_scans <> 164 THEN RAISE EXCEPTION 'expected 164 scans, found %', v_scans; END IF;

  SELECT count(*) INTO v_dup FROM derm.page_row_rules a
    JOIN derm.page_row_rules b ON b.dump_folder = a.dump_folder AND b.effective_page = a.effective_page
     AND b.source = a.source AND b.rule_pct > a.rule_pct AND b.rule_pct - a.rule_pct < 0.70
   WHERE a.source = 'runlen-v2-2026-08-21';
  IF v_dup <> 0 THEN RAISE EXCEPTION '% rule pairs closer than 0.70pp: one printed line counted twice', v_dup; END IF;

  -- 🛑 THE CONTROL THIS FILE EXISTS FOR: no served document may be invisible or unscanned.
  SELECT count(*) INTO v_unscanned FROM derm.v_band_edge_check WHERE edge_verdict = 'UNSCANNED';
  IF v_unscanned <> 0 THEN RAISE EXCEPTION '% served bands are UNSCANNED', v_unscanned; END IF;

  SELECT count(*) INTO v_derived FROM derm.v_band_edge_check WHERE NOT band_is_override;
  IF v_derived <> 9 THEN RAISE EXCEPTION 'expected the 9 derived-band documents to be visible, found %', v_derived; END IF;

  SELECT count(*) INTO v_lag FROM derm.v_band_edge_check WHERE NOT doc_current;
  IF v_lag > 20 THEN RAISE EXCEPTION '% documents lag a band edit, which is more than a sweep backlog', v_lag; END IF;

  SELECT count(*) INTO v_stale FROM derm.v_band_edge_check WHERE edge_verdict = 'STALE';
  IF v_stale <> 0 THEN RAISE EXCEPTION '% served bands read STALE', v_stale; END IF;

  -- and the structural checks must not have gone inert
  SELECT count(*) INTO v_span FROM derm.v_band_edge_check WHERE slot_verdict = 'SPANS_MULTIPLE';
  SELECT count(*) INTO v_part FROM derm.v_band_edge_check WHERE slot_verdict = 'PART_SLOT';
  IF v_span = 0 OR v_part = 0 THEN RAISE EXCEPTION 'a structural verdict is inert (span %, part %)', v_span, v_part; END IF;

  SELECT count(*) INTO v_ok FROM derm.v_band_edge_check
   WHERE edge_verdict = 'ON_RULE' AND slot_verdict = 'ONE_SLOT';
  IF v_ok < 540 THEN RAISE EXCEPTION 'only % provably clean bands', v_ok; END IF;

  RAISE NOTICE 'OK: % scans, % clean, % worklist, % derived bands now visible, % docs awaiting the sweep',
    v_scans, v_ok, (SELECT count(*) FROM derm.v_band_edges_off_rule), v_derived, v_lag;
END $$;

COMMIT;
